CREATE TRIGGER trg_api_keys_updated_at
  BEFORE UPDATE ON "api_keys"
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ── 20261011000000_trigram_and_seen_articles ──────────────────────────────
-- 1. Fuzzy community lookup (GET /gazetteer/lookup) calls similarity(), which needs pg_trgm.
--    Without the extension that endpoint fails with "function similarity does not exist".
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 2. Articles the scraper has already processed, relevant or not.
--    Before this table the scraper only skipped URLs already saved as reports, so every
--    run sent the same irrelevant articles to the language model again, and clean-up
--    articles (which create waste flows, not reports) were processed again each run.
CREATE TABLE IF NOT EXISTS "seen_articles" (
  "url"         TEXT         NOT NULL,
  "source"      TEXT,
  "outcome"     TEXT         NOT NULL,
  "first_seen"  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  CONSTRAINT "seen_articles_pkey" PRIMARY KEY ("url")
);

-- ── 20261011010000_api_key_internal_tier ──────────────────────────────────
-- The website's own API key. It is counted but not limited, so visitors need no key while partners do.
ALTER TYPE "ApiKeyTier" ADD VALUE IF NOT EXISTS 'INTERNAL';

-- ── 20261012000000_water_source_provenance ────────────────────────────────
-- Real water points imported from public datasets (WPDx, OpenStreetMap) need to say where
-- they came from, when they were surveyed and what state they were in.
ALTER TABLE "water_sources" ADD COLUMN IF NOT EXISTS "source_ref"        TEXT;
ALTER TABLE "water_sources" ADD COLUMN IF NOT EXISTS "data_source"       TEXT;
ALTER TABLE "water_sources" ADD COLUMN IF NOT EXISTS "surveyed_at"       TIMESTAMPTZ;
ALTER TABLE "water_sources" ADD COLUMN IF NOT EXISTS "condition"         TEXT;
ALTER TABLE "water_sources" ADD COLUMN IF NOT EXISTS "technology"        TEXT;
ALTER TABLE "water_sources" ADD COLUMN IF NOT EXISTS "population_served" INTEGER;
CREATE UNIQUE INDEX IF NOT EXISTS "water_sources_source_ref_key" ON "water_sources"("source_ref");

-- ── 20261012010000_import_references ──────────────────────────────────────
-- Partner spreadsheets (tonnage logs, water readings) are keyed by a reference column, so
-- uploading the same file twice skips what is already there instead of counting it twice.
ALTER TABLE "waste_flows"    ADD COLUMN IF NOT EXISTS "source_ref" TEXT;
ALTER TABLE "water_readings" ADD COLUMN IF NOT EXISTS "source_ref" TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS "waste_flows_source_ref_key"    ON "waste_flows"("source_ref");
CREATE UNIQUE INDEX IF NOT EXISTS "water_readings_source_ref_key" ON "water_readings"("source_ref");
